// 1. Get raw Gemini text output
const rawText =
  $input.first().json.content.parts[0].text;

// 2. Clean markdown fences
const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// 3. Parse JSON
let parsed;
try {
  parsed = JSON.parse(cleanedText);
} catch (err) {
  throw new Error('Invalid JSON from Gemini: ' + err.message);
}

// 4. Validate required top-level keys
const requiredKeys = [
  'projectId',
  'sessionId',
  'area',
  'transcriptSegments',
  'tasks',
  'issues',
  'questions',
  'changeOrderCandidates',
  'dailyLog',
  'audit'
];

for (const key of requiredKeys) {
  if (!(key in parsed)) {
    throw new Error(`Missing required key: ${key}`);
  }
}

// 5. Ensure dailyLog.summaryBullets are objects with text field
if (parsed.dailyLog && Array.isArray(parsed.dailyLog.summaryBullets)) {
  parsed.dailyLog.summaryBullets = parsed.dailyLog.summaryBullets.map((bullet, idx) => {
    if (typeof bullet === 'string') {
      return {
        bulletId: `bullet_auto_${idx}`,
        text: bullet,
        category: 'work_performed',
        source_audio_note_id: '',
        source_transcript_segment_ids: [],
        linkTranscriptSegmentIds: []
      };
    }
    return bullet;
  });
}

// 6. Ensure transcript segments have speaker field
if (Array.isArray(parsed.transcriptSegments)) {
  parsed.transcriptSegments = parsed.transcriptSegments.map(seg => ({
    ...seg,
    speaker: seg.speaker || 'Unknown Speaker',
    diarizationConfidence: seg.diarizationConfidence || 0
  }));
}

// 7. Return clean validated JSON
return {
  json: parsed
};
